    const table = cfg?.approximate; const pdx = String(diagnoses[0]?.code || '');
    if (table) { const key = Object.keys(table).filter((k) => pdx.startsWith(k)).sort((a, b) => b.length - a.length)[0]; if (key) { const sec = diagnoses.slice(1).map((d) => d.code); const tier = sec.some((d) => (cfg.mcc || []).some((m) => d.startsWith(m))) ? 'mcc' : sec.some((d) => (cfg.cc || []).some((m) => d.startsWith(m))) ? 'cc' : 'none'; const drg = table[key][tier] || table[key].none; if (drg) return { drg: String(drg).padStart(3, '0'), method: 'our own table from the public definitions', approximate: true, label: 'approximate', tier, ...(failed ? { note: `the official grouper could not be run: ${failed}` } : {}) }; } }
