      const id = `CL${randomUUID().slice(0, 8).toUpperCase()}`; let lines = cd.lines.map((l) => ({ ...l }));
      if (kind === 'institutional') { lines = cd.setting === 'inpatient' ? [{ n: 1, revenue: st.revenue, code: lines[0].code, modifiers: [], units: Math.max(1, Math.round((Date.parse(cd.dischargedAt || at) - Date.parse(cd.admittedAt || at)) / 864e5)), date: day(cd.admittedAt || at), charge: lines[0].charge }, ...lines.slice(1).map((l, i) => ({ ...l, n: i + 2, revenue: l.revenue || '0300' }))] : lines.map((l) => ({ ...l, code: cd.setting === 'hospital-clinic' && /^992[01]\d$/.test(l.code) ? st.visitCode : l.code, revenue: l.revenue || st.revenue })); }
